/// The key `scripts/gen_shader_object_rendering.py` names a fragment shader by.
pub fn program_key(
    color_count: u32,
    extra_attachments: u32,
    extra_attachment_kind: u32,
    extra_outputs: u32,
    extra_output_kind: u32,
    class: u32,
    random: bool,
    frag_depth: bool,
    array: bool,
) -> String {
    format!(
        "c{color_count}a{extra_attachments}{extra_attachment_kind}o{extra_outputs}{extra_output_kind}t{class}r{}d{}y{}",
        u32::from(random),
        u32::from(frag_depth),
        u32::from(array)
    )
}

